#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t error)
{
    if (error != cudaSuccess) {
        std::fprintf(stderr, "%s\n", cudaGetErrorString(error));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void sum_valid(const float* input, unsigned valid,
                          float* output)
{
    __shared__ float values[96];
    const unsigned i = threadIdx.x;

    // The unselected operand is not evaluated: no invalid input read.
    values[i] = i < valid ? input[i] : 0.0f;
    __syncthreads();

    if (i == 0) {
        float sum = 0.0f;
        for (unsigned j = 0; j < valid; ++j) {
            sum += values[j];
        }
        *output = sum;
    }
}

int main(int argc, char** argv)
{
    unsigned valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        const long parsed = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' ||
            parsed < 0 || parsed > 96) {
            std::fprintf(stderr, "valid must be an integer in 0..96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<unsigned>(parsed);
    }

    float input[96];
    for (float& value : input) value = 1.0f;
    float result = -1.0f;
    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    check(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    check(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    check(cudaMalloc(&device_input, sizeof(input)));
    check(cudaMalloc(&device_output, sizeof(result)));
    check(cudaMemcpy(device_input, input, sizeof(input),
                     cudaMemcpyHostToDevice));

    sum_valid<<<1, 96, 0, stream>>>(device_input, valid, device_output);
    check(cudaGetLastError());
    check(cudaEventRecord(done, stream));
    check(cudaEventSynchronize(done));
    check(cudaMemcpy(&result, device_output, sizeof(result),
                     cudaMemcpyDeviceToHost));
    std::printf("sum = %.9g\n", static_cast<double>(result));

    check(cudaFree(device_output));
    check(cudaFree(device_input));
    check(cudaEventDestroy(done));
    check(cudaStreamDestroy(stream));
    return EXIT_SUCCESS;
