B’s wait references E’s first record, because that was the most recent record when the wait was submitted. Recording E again does not retarget that existing wait. P2 can race with C1: producer completion transfers permission to read, but does not establish permission to overwrite.

I interpret “weight” as `cudaStreamWaitEvent`. A permitted trace is:
1. Host submits P1 → record E₁ in A; wait E₁ → C1 in B; then P2 → record E₂ in A.
2. GPU completes P1 and E₁, satisfying B’s wait.
3. A starts P2 while B starts C1. They access the same allocation without an ordering dependency, so their write/read can race.
4. A query after the second record refers to E₂ and can return `cudaErrorNotReady`. It says nothing about whether C1 has finished and does not change B’s existing wait.

Use two slots, each with its own ready and consumed events. First use skips the consumed wait because that event has not yet been recorded. Subsequent reuse makes A wait for that slot’s previous consumer; no host synchronization occurs between iterations.

```cuda
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

static void check(cudaError_t error)
{
    if (error != cudaSuccess) {
        std::fprintf(stderr, "CUDA: %s\n", cudaGetErrorString(error));
        std::exit(EXIT_FAILURE);
    }
}

__global__ void producer(float* slot, float value)
{
    *slot = value;
}

__global__ void consumer(const float* slot, float* result)
{
    *result = *slot;
}

struct Slot {
    float* data = nullptr;
    cudaEvent_t ready{};
    cudaEvent_t consumed{};
    bool used = false;
};

int main()
{
    constexpr int count = 8;
    cudaStream_t A, B;
    check(cudaStreamCreateWithFlags(&A, cudaStreamNonBlocking));
    check(cudaStreamCreateWithFlags(&B, cudaStreamNonBlocking));

    Slot slots[2];
    for (Slot& slot : slots) {
        check(cudaMalloc(reinterpret_cast<void**>(&slot.data),
                         sizeof(float)));
        check(cudaEventCreateWithFlags(&slot.ready,
                                       cudaEventDisableTiming));
        check(cudaEventCreateWithFlags(&slot.consumed,
                                       cudaEventDisableTiming));
    }

    float* device_results = nullptr;
    check(cudaMalloc(reinterpret_cast<void**>(&device_results),
                     count * sizeof(float)));

    for (int i = 0; i < count; ++i) {
        Slot& slot = slots[i % 2];

        // Capture the previous consumed record before it is rerecorded.
        // First use has no previous consumer and needs no wait.
        if (slot.used) {
            check(cudaStreamWaitEvent(A, slot.consumed, 0));
        }

        producer<<<1, 1, 0, A>>>(slot.data, static_cast<float>(i + 1));
        check(cudaGetLastError());
        check(cudaEventRecord(slot.ready, A));

        // Capture this iteration's ready record.
        check(cudaStreamWaitEvent(B, slot.ready, 0));
        consumer<<<1, 1, 0, B>>>(slot.data, device_results + i);
        check(cudaGetLastError());
        check(cudaEventRecord(slot.consumed, B));
        slot.used = true;
    }

    // Final drain only: no synchronization inside the iteration loop.
    check(cudaStreamSynchronize(B));
    check(cudaStreamSynchronize(A));

    float results[count];
    check(cudaMemcpy(results, device_results, sizeof(results),
                     cudaMemcpyDeviceToHost));
    for (int i = 0; i < count; ++i) {
        if (results[i] != static_cast<float>(i + 1)) {
            std::fprintf(stderr, "Incorrect result at %d\n", i);
            return EXIT_FAILURE;
        }
    }
    std::puts("All results correct");

    for (Slot& slot : slots) {
        check(cudaEventDestroy(slot.ready));
        check(cudaEventDestroy(slot.consumed));
        check(cudaFree(slot.data));
    }
    check(cudaFree(device_results));
    check(cudaStreamDestroy(B));
    check(cudaStreamDestroy(A));
    return EXIT_SUCCESS;
}
```

